import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class MoneyTest {

    @Test
    void additionne_deux_montants() {
        // Arrange
        var a = new Money(100, "EUR");
        var b = new Money(50, "EUR");

        // Act
        var total = a.add(b);

        // Assert
        assertEquals(150, total.cents());
    }
}
